// English UI strings and prompt templates.
import type { Locale } from '../types';

const COURSE = '"Learn Finance with AI"';
const DISCLAIMER =
	'All lessons, questions and reference answers in this course were generated by AI and have not been reviewed by a professional. They may contain errors.';

const locale: Locale = {
	ui: {
		lessonPrefix: 'Lesson {id}',
		lessonPlain: 'Lesson {id}, "{title}"',
		lessonUnpublished: 'Lesson {id}, not yet published',
		unpublished: 'not yet published',
		paren: ' ({text})',
		forwardHint: 'Content from a later lesson. You do not need to master it now.',
		figure: 'Figure {id}',
		check: 'Check {id}',
		exerciseItem: 'Question {n}',
		observe: 'Observe: ',
		checksTitle: 'Submit the check questions',
		checksHelp: 'The check questions of this lesson are submitted together here.',
		copyHint: 'Paste the prompt into your AI assistant, then attach a photo of your answers or type your answers after the prompt. You can submit all your answers at once or in several parts.',
		copiedGrading: 'Copied. Paste it into your AI assistant.',
		copiedExplain: 'Explanation prompt copied',
		notAnswered: 'Not answered',
		quizItem: 'Question {n}',
		points: '{n} points',
		scoreOf: '{s}/{m} points',
		copyGrading: 'Copy scoring prompt',
		quizPartJudge: 'Part 1. True or false',
		quizPartJudgeHelp: 'Answer true or false, and give your reason. An answer without a reason gets no points.',
		quizPartProblems: 'Part 2. Problems',
		quizSubmit: 'Submit the quiz',
		lessonNotStarted: 'Not started',
		lessonInProgress: 'In progress',
		lessonDone: 'Done',
		copyFeedback: 'Copy feedback prompt',
		statusOk: 'OK',
		statusRevise: 'needs revision',
		pasteResult: 'Paste the result from your AI',
		pasteHint: 'Paste the part of the AI reply between <<<LFWAI-RESULT and LFWAI-RESULT>>> (or the whole reply) here.',
		saveResult: 'Save result',
		saved: 'Saved.',
		parseFailed: 'No result block was found. Make sure you pasted the part of the reply that starts with <<<LFWAI-RESULT.',
		promptTitle: 'Copy the prompt below',
		promptHelp: 'Automatic copying did not work. Select all of the text below and copy it.',
		copy: 'Copy',
		copied: 'Copied',
		close: 'Close',
		explain: 'Explain this',
		aiNoticeTitle: 'This content was generated by AI. It may contain errors and is not investment advice.',
		aiNotice: 'All lessons, questions and reference answers on this site were generated by AI and have not been reviewed by a professional. Their correctness is not guaranteed. If you find an error, please report it with the link at the bottom of the page. The content is for learning only and is not investment advice.',
		reportError: 'Report an error on this page',
		reportTitle: '[Content error] {page}',
		reportBody: 'Page: {url}\n\nWhere is the error (copy the original text):\n\nWhat is wrong:\n',
		exercisesHeading: 'Exercises',
		prevPage: 'Previous',
		nextPage: 'Next',
		heroChart: '1 dollar growing at 7% a year, compounded',
		heroChartEnd: '{v} dollars',
		heroYears: '{n} years',
		continueAt: 'Continue: {title}',
		routeTitle: 'The course',
		routePublished: 'published',
		routeUpcoming: 'being written',
		routeQuiz: 'quiz',
	},

	prompts: {
		feedback(i, p) {
			const qs = i.questions
				.map(
					(q) => `### ${q.label} (id: ${q.id})
Question:
${q.question}

Reference answer:
${q.answer}

What to check:
${p.bullets(q.rubric)}`,
				)
				.join('\n\n');
			return `You are a teacher for the course ${COURSE}. Review the learner's answers for Lesson ${i.lessonId}, "${i.lessonTitle}". The learner's answers follow this prompt (a photo or text) and may cover only some of the questions.

## Important
${DISCLAIMER} If you believe a reference answer or a checking point is itself wrong, say clearly what is wrong and judge against the correct answer. Do not mark the learner wrong because they did not copy a wrong reference answer.

## Lesson page
${i.lessonUrl}
(You may consult it if you can open web pages. If you cannot, that is fine: everything you need is written below.)

## Lesson facts relevant to these questions
${p.bullets(i.context)}

## Questions, reference answers and what to check
${qs}
${i.commonErrors.length ? `\n## Common errors (for diagnosis)\n${p.bullets(i.commonErrors)}\n` : ''}
## How to reply
1. These questions are **not scored**. Review only the questions the learner answered this time. Do not mention unanswered questions; they will be submitted later.
2. For each question, say what is correct and what is wrong. Check the reasoning, not only the final numbers.
3. For each error, explain it in a way the learner can understand, with a small example if useful. Do not only repeat the reference answer.
4. If an answer shows a misunderstanding of a concept, name the concept.
5. Reply in English. Use LaTeX for formulas.
6. At the end of your reply, output a result block in exactly this format. The JSON must be valid:

${p.resultBlock}

List only the questions you reviewed in "items", one entry per question. Set "status" to "ok" (essentially correct, only minor issues) or "revise" (a substantive error that needs to be corrected). Question ids: ${i.questions.map((q) => q.id).join(', ')}.

## The learner's answers
`;
		},

		quiz(i, p) {
			const qs = i.questions
				.map(
					(q) => `### ${q.label} (id: ${q.id}, ${q.points} points)
Question:
${q.question}

Reference answer:
${q.answer}

Scoring points:
${p.bullets(q.rubric)}`,
				)
				.join('\n\n');
			return `You are a teacher for the course ${COURSE}. Score the learner's answers for "${i.lessonTitle}". The learner's answers follow this prompt (a photo or text) and may cover only some of the questions.

## Important
${DISCLAIMER} If you believe a reference answer or a scoring point is itself wrong, say clearly what is wrong and score against the correct answer. Do not take points off because the learner did not copy a wrong reference answer.

## Quiz page
${i.lessonUrl}
(You may consult it if you can open web pages. If you cannot, that is fine: everything you need is written below.)

## Lesson facts relevant to these questions
${p.bullets(i.context)}

## Questions, reference answers and scoring points
${qs}
${i.commonErrors.length ? `\n## Common errors (for diagnosis)\n${p.bullets(i.commonErrors)}\n` : ''}
## Scoring rules
- Score only the questions the learner answered this time. Do not score unanswered questions and do not give them 0; they will be submitted later.
- Score by the scoring points; partial credit is allowed. In calculation questions, parts without working get no points; if the working is partly correct, give the points that the scoring points assign to it.
- In true / false questions, an answer without a reason gets no points.
- When a question asks for a given number of reasons or answers, score only that number, in the order written; extra ones are not scored.

## How to reply
1. Give the score for each question and say what is correct and what is wrong. Check the reasoning, not only the final numbers.
2. For each lost point, explain the problem in a way the learner can understand, with a small example if useful. Do not only repeat the reference answer.
3. Reply in English. Use LaTeX for formulas.
4. At the end of your reply, output a result block in exactly this format. The JSON must be valid:

${p.resultBlock}

List only the questions you scored in "items", one entry per question, with the actual score in "score" and the full points in "max". Question ids and full points: ${i.questions.map((q) => `${q.id} (${q.points})`).join(', ')}.

## The learner's answers
`;
		},

		explain(i, p) {
			const where = i.lessonId ? `Lesson ${i.lessonId}, "${i.lessonTitle}"` : `the page "${i.pageTitle}"`;
			const parts = [
				`I am studying ${where} in the course ${COURSE}, and I do not understand a passage. Please explain it in more detail.
Note: ${DISCLAIMER} If you find that the passage itself is wrong, please say so directly.

Page: ${i.pageUrl}
Section: ${i.section || '(none)'}

The text I selected:
${p.fence(i.selection)}`,
			];
			if (i.paragraph.trim() !== i.selection.trim()) parts.push(`The paragraph it is in:\n${p.fence(i.paragraph)}`);
			if (i.context) parts.push(`Key points of the lesson (for context):\n${i.context}`);
			parts.push(`Please explain it this way:
1. First state the meaning of the passage in one or two sentences.
2. Then explain why it is true, and fill in any steps that were skipped. If there is a formula, explain what each symbol means.
3. Give a small concrete example, preferably with numbers.
4. If the passage depends on concepts from earlier lessons, briefly remind me of them. Do not teach content from later lessons unless it is necessary to understand this passage.
5. End with one short question that lets me check my understanding (do not give the answer yet).
Reply in English. Use LaTeX for formulas.`);
			return parts.join('\n\n') + '\n';
		},
	},
};

export default locale;
